entries[327161] = { ["name"] = "Primordial Wave", ["text"] = "Covenant Ability\n100 yd range\nInstant\nRestoration\nBlast your target with a Primordial Wave, dealing (65% of Spell Power) Shadow damage and apply Flame Shock to an enemy, or heal an ally for (65% of Spell Power) and apply Riptide to them.\n\nYour next Healing Wave will also hit all targets affected by your Riptide for 60% of normal healing.\n\nElemental\nBlast your target with a Primordial Wave, dealing (65% of Spell Power) Shadow damage and apply Flame Shock to an enemy, or heal an ally for (65% of Spell Power).\n\nYour next Lava Burst will also hit all targets affected by your Flame Shock for 80% of normal damage.\n\nEnhancement\nBlast your target with a Primordial Wave, dealing (65% of Spell Power) Shadow damage and apply Flame Shock to an enemy, or heal an ally for (65% of Spell Power).\n\nYour next Lightning Bolt will also hit all targets affected by your Flame Shock for 150% of normal damage." }
entries[327162] = { ["name"] = "Primordial Wave", ["text"] = "Covenant Ability\n100 yd range\nInstant\nRestoration\nBlast your target with a Primordial Wave, dealing (65% of Spell Power) Shadow damage and apply Flame Shock to an enemy, or heal an ally for (65% of Spell Power) and apply Riptide to them.\n\nYour next Healing Wave will also hit all targets affected by your Riptide for 60% of normal healing.\n\nElemental\nBlast your target with a Primordial Wave, dealing (65% of Spell Power) Shadow damage and apply Flame Shock to an enemy, or heal an ally for (65% of Spell Power).\n\nYour next Lava Burst will also hit all targets affected by your Flame Shock for 80% of normal damage.\n\nEnhancement\nBlast your target with a Primordial Wave, dealing (65% of Spell Power) Shadow damage and apply Flame Shock to an enemy, or heal an ally for (65% of Spell Power).\n\nYour next Lightning Bolt will also hit all targets affected by your Flame Shock for 150% of normal damage." }
